#!/usr/bin/env python3
"""Verify recovery after removing staged fixture inputs generated by real Nextflow.

Only tasks bearing the explicit NESTED_STAGING_FIXTURE marker are modified.
This intentionally exercises wrapper parsing, not a hand-built imitation.
"""
import argparse
import importlib.util
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
spec=importlib.util.spec_from_file_location('join_investigation',ROOT/'scripts/comparisons/join_investigation.py')
mod=importlib.util.module_from_spec(spec);spec.loader.exec_module(mod)


def main():
    p=argparse.ArgumentParser();p.add_argument('work',type=Path);a=p.parse_args();work=a.work.resolve()
    tested=[]
    for wrapper in work.glob('*/*/.command.run'):
        task=wrapper.parent.resolve()
        if '# NESTED_STAGING_FIXTURE' not in (task/'.command.sh').read_text():continue
        assert task.is_relative_to(work)
        mappings=[(dest,source) for dest,source in mod.staged_links(task) if dest.parent.name=='agp']
        assert len(mappings)==1,(wrapper,mappings)
        destination,source=mappings[0]
        assert destination.is_relative_to(task) and destination!=source
        original=source.read_bytes()
        destination.unlink()  # Remove only the fixture's staged file/link, never its source.
        recovered=mod.retained_input(task,destination.relative_to(task))
        assert recovered==str(source.resolve()),(recovered,source)
        assert source.read_bytes()==original
        tested.append(task)
    assert len(tested)==3,f'Expected symlink, copy and hard-link tasks, found {len(tested)}'
    print('PASS: recovered removed nested inputs from three real Nextflow wrappers (symlink, copy, hard link)')


if __name__=='__main__':main()
